var ul = tree.current_scene.unit_list
var idx = -1
for i in range(ul.get_item_count()):
	if str(ul.get_item_metadata(i)) == "U_CUSTODIAN_GUARD_A":
		idx = i
return idx

var main = tree.current_scene
var dc = main.deployment_controller
var tl = main.get_node("BoardRoot/TokenLayer")
var ids = ["U_CUSTODIAN_GUARD_A"]
var parts = []
for uid in ids:
	var u = GameState.state.units[uid]
	var pos_n = 0
	for m in u.models:
		if m.get("position") != null:
			pos_n += 1
	var tok = 0
	for c in tl.get_children():
		if c.has_meta("unit_id") and str(c.get_meta("unit_id")) == uid:
			tok += 1
	parts.append("%s st=%d pos=%d/%d tok=%d" % [uid, int(u.status), pos_n, u.models.size(), tok])
var listed = false
for i in range(main.unit_list.get_item_count()):
	if str(main.unit_list.get_item_metadata(i)) == ids[0]:
		listed = true
parts.append("previews=%d placing=%s listed=%s" % [dc.placed_tokens.size(), str(dc.is_placing()), str(listed)])
var r = " | ".join(parts)
print("SCENARIO human_composite_deploy report: " + r)
return r

