var u = GameState.state.units["U_WARBIKERS_A"]
var hits = []
for m in u.models:
	var t = m.duplicate()
	var p = m.get("position")
	t["position"] = Vector2(float(p.x), float(p.y))
	var h = TerrainManager.solid_terrain_endpoint_blocker_11e(t, u.meta.keywords)
	if h != "":
		hits.append(h)
return str(hits)

var stranded = []
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("status", 0)) == 1 and uid != tree.current_scene.deployment_controller.unit_id:
		stranded.append(uid)
	if int(u.get("status", 0)) == 2 and u.get("embarked_in", null) == null:
		for m in u.models:
			if m.get("alive", true) and m.get("position") == null:
				stranded.append(uid + ":nopos")
				break
return str(stranded)
